**Complete ANSI C program** (Task 2 subprograms, Task 3 subprograms and `main`, in one file):

```c
#include <stdio.h>

#define ROW 4                  /* number of rows    (Row in the statement) */
#define COL 4                  /* number of columns (Col in the statement) */
#define RAND_SEED 7            /* default random number seed */

int Rand_x = RAND_SEED;        /* global variable: current state of the generator */

/* seed (initialise) the RNG with an integer s, where 0 < s < 16 */
void Rand_init(int s)
{
    if (s > 0 && s < 16)
        Rand_x = s;
}

/* return the next random number: 0 or 1 */
int Rand_no(void)
{
    Rand_x = (5 * Rand_x + 3) % 16;
    return Rand_x % 2;
}

void row_line(void)
{
    int j;

    printf("\n");
    for (j = 0; j < COL; j++)
        printf(" -----");
    printf("\n");
}

void Gen_cells(int A[][COL], int row, int col)
{
    int i, j;

    for (i = 0; i < row; i++)
        for (j = 0; j < col; j++)
            A[i][j] = Rand_no();       /* randomly insert a 0 or 1 */
}

int count_live_neighs(int A[][COL], int r, int c)
{
    int i, j, count = 0;

    for (i = r - 1; i <= r + 1; i++)
        for (j = c - 1; j <= c + 1; j++)
            if (!(i == r && j == c))                              /* not the cell itself */
                if (!((i < 0 || j < 0) || (i >= ROW) || (j >= COL)))   /* valid indices */
                    if (A[i][j] == 1)
                        count++;
    return count;
}

void Next_Gen(int A[][COL], int B[][COL])
{
    int i, j, n_live;

    for (i = 0; i < ROW; i++)
        for (j = 0; j < COL; j++) {
            n_live = count_live_neighs(A, i, j);
            if (A[i][j] == 1 && (n_live == 2 || n_live == 3))
                B[i][j] = 1;
            else if (A[i][j] == 0 && n_live == 3)
                B[i][j] = 1;
            else
                B[i][j] = 0;
        }
}

void print_rows(int X[][COL], int row, int col)
{
    int i, j;

    for (i = 0; i < row; i++) {
        row_line();
        for (j = 0; j < col; j++)
            printf("|  %d  ", X[i][j]);      /* a bar, two spaces, the value, two spaces */
        printf("|");                         /* final bar (no new line: row_line() starts one) */
    }
    row_line();
}

void PrintMat(int A[][COL], int row, int col)
{
    printf("Initial Stage:");
    print_rows(A, row, col);
}

void PrintNextGen(int B[][COL], int row, int col)
{
    printf("Next Generation:");
    print_rows(B, row, col);
}

int main(void)
{
    int A[ROW][COL], B[ROW][COL];
    int s;

    do {                                    /* the seed must satisfy 0 < s < 16 */
        printf("Enter the seed s (1 to 15): ");
        if (scanf("%d", &s) != 1)
            return 1;
    } while (s <= 0 || s >= 16);

    Rand_init(s);
    Gen_cells(A, ROW, COL);
    PrintMat(A, ROW, COL);
    Next_Gen(A, B);
    PrintNextGen(B, ROW, COL);
    return 0;
}
```

**Complete ISO Pascal program** (the same logic; arrays are numbered from 1, so the loops of the printed algorithms can be kept; array parameters are passed with `var`; a variable cannot be initialised in its declaration in ISO Pascal, so `Rand_x` receives its default value at the start of the main program):

```pascal
program GameOfLife(input, output);

const
  ROW = 4;
  COL = 4;
  RAND_SEED = 7;

type
  TBoard = array[1..ROW, 1..COL] of integer;

var
  Rand_x, s : integer;
  A, B      : TBoard;

procedure Rand_init(s : integer);
begin
  if (s > 0) and (s < 16) then
    Rand_x := s
end;

function Rand_no : integer;
begin
  Rand_x := (5 * Rand_x + 3) mod 16;
  Rand_no := Rand_x mod 2
end;

procedure row_line;
var
  j : integer;
begin
  writeln;
  for j := 1 to COL do
    write(' -----');
  writeln
end;

procedure Gen_cells(var A : TBoard; row, col : integer);
var
  i, j : integer;
begin
  for i := 1 to row do
    for j := 1 to col do
      A[i, j] := Rand_no
end;

function count_live_neighs(var A : TBoard; r, c : integer) : integer;
var
  i, j, count : integer;
begin
  count := 0;
  for i := r - 1 to r + 1 do
    for j := c - 1 to c + 1 do
      if not ((i = r) and (j = c)) then
        if (i >= 1) and (i <= ROW) and (j >= 1) and (j <= COL) then
          if A[i, j] = 1 then
            count := count + 1;
  count_live_neighs := count
end;

procedure Next_Gen(var A, B : TBoard);
var
  i, j, n_live : integer;
begin
  for i := 1 to ROW do
    for j := 1 to COL do
    begin
      n_live := count_live_neighs(A, i, j);
      if (A[i, j] = 1) and ((n_live = 2) or (n_live = 3)) then
        B[i, j] := 1
      else if (A[i, j] = 0) and (n_live = 3) then
        B[i, j] := 1
      else
        B[i, j] := 0
    end
end;

procedure print_rows(var X : TBoard; row, col : integer);
var
  i, j : integer;
begin
  for i := 1 to row do
  begin
    row_line;
    for j := 1 to col do
      write('|  ', X[i, j]:1, '  ');
    write('|')
  end;
  row_line
end;

procedure PrintMat(var A : TBoard; row, col : integer);
begin
  write('Initial Stage:');
  print_rows(A, row, col)
end;

procedure PrintNextGen(var B : TBoard; row, col : integer);
begin
  write('Next Generation:');
  print_rows(B, row, col)
end;

begin
  Rand_x := RAND_SEED;                  { global default value }
  repeat
    write('Enter the seed s (1 to 15): ');
    readln(s)
  until (s > 0) and (s < 16);

  Rand_init(s);
  Gen_cells(A, ROW, COL);
  PrintMat(A, ROW, COL);
  Next_Gen(A, B);
  PrintNextGen(B, ROW, COL)
end.
```

